<section class="table-card">
    <div class="card-head"><h2>Product Catalog</h2><a class="btn btn-primary btn-sm" href="<?= url('admin/product-form') ?>">Add Product</a></div>
    <form class="admin-filters admin-filters-wide" method="get" action="<?= url('admin/products') ?>"><input name="q" placeholder="Search product or category" value="<?= h($_GET['q'] ?? '') ?>"><select name="category_id"><option value="">All categories</option><?php foreach ($categories as $cat): ?><option value="<?= $cat['id'] ?>" <?= (int)($_GET['category_id'] ?? 0) === (int)$cat['id'] ? 'selected' : '' ?>><?= h($cat['name']) ?></option><?php endforeach; ?></select><select name="status"><option value="">All statuses</option><option value="active" <?= ($_GET['status'] ?? '') === 'active' ? 'selected' : '' ?>>Active</option><option value="hidden" <?= ($_GET['status'] ?? '') === 'hidden' ? 'selected' : '' ?>>Hidden</option></select><button class="btn btn-outline btn-sm">Filter</button></form>
    <table class="data-table"><thead><tr><th class="thumb-col">Image</th><th>Name</th><th>Category</th><th>Price From</th><th>Stock</th><th>Status</th><th class="action-col">Actions</th></tr></thead><tbody>
        <?php foreach ($products as $product): ?><tr><td><img class="admin-thumb" src="<?= asset($product['image_path'] ?? 'public/assets/images/products/product-01.png') ?>" alt=""></td><td><strong><?= h($product['name']) ?></strong><span class="muted block"><?= h($product['short_description']) ?></span></td><td><?= h($product['category_name']) ?></td><td class="num"><?= money($product['min_price']) ?></td><td class="num"><?= h($product['stock']) ?></td><td class="center"><span class="status <?= $product['is_active']?'status-delivered':'status-cancelled' ?>"><?= $product['is_active']?'Active':'Hidden' ?></span></td><td class="actions"><a class="icon-button" href="<?= url('admin/product-form', ['id'=>$product['id']]) ?>">&#9998;</a><form method="post" action="<?= url('admin/product-delete') ?>" onsubmit="return confirm('Hide this product?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= h($product['id']) ?>"><button class="icon-button danger" type="submit">&times;</button></form></td></tr><?php endforeach; ?>
    </tbody></table>
</section>
